// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Folio} from "folio/Folio.sol";
import {IFolio} from "folio/interfaces/IFolio.sol";
import {MintSplit} from "./FixedFeeRegistry.sol";

/// @notice Creation, funding and fee policy shared by every index this protocol launches.
///
/// @dev    Atomically funds and initializes an immutable implementation clone. The caller
///         receives all initial shares and admin authority; this contract retains neither assets
///         nor roles.
///
///         ## WHY THIS IS A BASE AND NOT THE ENTRY POINT
///
///         `create` here produces an index with **no mandate and no market**: the creator holds
///         admin directly and nothing rebalances. That is the right shape for a base class and
///         the wrong shape for a product, so it is `internal` machinery plus a bare `create` kept
///         for tests. `IndexFactory.createManaged` is the production path and it binds a
///         `MonthlyMandate` before returning.
contract IndexFactoryBase is ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public immutable implementation;
    address public immutable feeRegistry;
    mapping(address => bool) public isIndex;
    error InvalidConfiguration();
    error UnsupportedTransfer(address token);
    event IndexCreated(address indexed index, address indexed creator, string engineVersion);

    constructor(address implementation_, address feeRegistry_) {
        if (implementation_.code.length == 0 || feeRegistry_.code.length == 0) revert InvalidConfiguration();
        implementation = implementation_;
        feeRegistry = feeRegistry_;
    }

    function create(IFolio.FolioBasicDetails calldata seed) external virtual nonReentrant returns (Folio index) {
        index = _create(seed);
        index.grantRole(bytes32(0), msg.sender);
        index.renounceRole(bytes32(0), address(this));
    }

    function _create(IFolio.FolioBasicDetails calldata seed) internal returns (Folio index) {
        return _createFor(seed, msg.sender, msg.sender);
    }

    /**
     * @dev Create with the initial shares going somewhere other than the creator.
     *
     *      `shareRecipient` exists so a seeded launch can hold the shares long enough to open the
     *      market with them, and pass on what is left. `creator` stays the fee recipient and the
     *      admin either way: who paid for the basket and who happens to custody the shares for
     *      one transaction are different questions, and conflating them would hand the factory a
     *      cut of every mint.
     */
    function _createFor(IFolio.FolioBasicDetails calldata seed, address shareRecipient, address creator)
        internal
        returns (Folio index)
    {
        uint256 n = seed.assets.length;
        if (n == 0 || n > 16 || n != seed.amounts.length || seed.initialShares < 1e18) {
            revert InvalidConfiguration();
        }
        index = Folio(Clones.clone(implementation));
        for (uint256 i; i < n; ++i) {
            if (seed.assets[i].code.length == 0 || seed.amounts[i] == 0) revert InvalidConfiguration();
            for (uint256 j; j < i; ++j) {
                if (seed.assets[i] == seed.assets[j]) revert InvalidConfiguration();
            }
            IERC20 token = IERC20(seed.assets[i]);
            uint256 beforeBalance = token.balanceOf(address(index));
            token.safeTransferFrom(msg.sender, address(index), seed.amounts[i]);
            if (token.balanceOf(address(index)) != beforeBalance + seed.amounts[i]) {
                revert UnsupportedTransfer(seed.assets[i]);
            }
        }
        IFolio.FeeRecipient[] memory recipients = new IFolio.FeeRecipient[](1);
        recipients[0] = IFolio.FeeRecipient(creator, 1e18);
        index.initialize(
            seed,
            IFolio.FolioAdditionalDetails({
                maxAuctionLength: 1 hours,
                feeRecipients: recipients,
                immutableFeeRecipients: new IFolio.FeeRecipient[](0),
                /*
                 * No yearly fee, and 0.50% on a mint: 20 bps to the protocol, 15 to holders and
                 * 15 to the creator. `MintSplit` has the arithmetic.
                 *
                 * **No yearly fee is the holder guarantee.** Holding costs nothing, and trading and
                 * minting both pay holders, so a holder is ahead at any volume above zero. A yearly
                 * fee paid by holders would need volume many times the index's size to recover.
                 * The registry's floor must be zero too, or Folio raises this back to the floor.
                 *
                 * **The mint fee is the tracking band.** A share can trade up to about 0.50% plus
                 * the pool's 0.40% above net asset value before minting to sell into the premium
                 * is worth anyone's while. It was 1.35%, three to four times what comparable
                 * indexes charge, which let buyers pay a premium the basket did not justify. There
                 * is no redeem fee to match it: Folio has none, and `redeem` is directly callable
                 * so a wrapper would be bypassable.
                 *
                 * The holders' part is Folio's own `folioFeeForSelf`: those shares are handed out
                 * to backing over a ten-minute window each day at a capped rate, so buying just
                 * before a mint to catch it gains nothing.
                 */
                tvlFee: 0,
                mintFee: MintSplit.MINT_FEE,
                folioFeeForSelf: MintSplit.HOLDER_PORTION,
                mandate: "LOCAL PROTOTYPE: direct creator admin; no enforced investment mandate"
            }),
            IFolio.FolioRegistryIndex(feeRegistry, address(0)),
            IFolio.FolioFlags({
                trustedFillerEnabled: false,
                rebalanceControl: IFolio.RebalanceControl(false, IFolio.PriceControl.NONE),
                bidsEnabled: true
            }),
            shareRecipient
        );
        isIndex[address(index)] = true;
        emit IndexCreated(address(index), creator, index.version());
    }
}

src/MonthlyMandate.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Folio} from "folio/Folio.sol";
import {IFolio} from "folio/interfaces/IFolio.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

/// @notice Manual mandate with notice, price approval and one auction per cycle, over a token universe
///         that grows only by announcement.
/// @dev Bounds are raw-token quantities per basket unit, NOT percentage-of-NAV guarantees.
/// The reviewer is trusted to assess current prices; this is not an autonomous oracle policy.
///
/// **v3: prices are set when the auction starts, not when it is queued.** A queued proposal commits to
/// weights and to a reference price per token (its band's `low`, the planning price). Hours or days
/// later the reviewer approves with one fresh price per token, and this contract builds the auction's
/// bands from them, in the shape that protects the index: a token the index sells gets its band from
/// just under the fresh price upward, a token it buys from just over it downward, so every pair
/// starts in the index's favour and ends at most about `2 * EDGE_BPS` past the fresh prices.
///
/// What a reviewer can do with prices is bounded. Only relative moves between tokens can cost the
/// index anything (moving every price together changes no pair), so the fresh prices may move
/// against their references by at most `MAX_RELATIVE_BPS` relative to each other, and no one price
/// by more than `MAX_REPRICE_BPS`. A market that moved further since the queue needs a new proposal.
/// The approval lasts at most five minutes, so an auction never runs on prices more than minutes old.
/// No arbitrary calls, engine role grants, withdrawals, fee changes or upgrades are exposed.
contract MonthlyMandate is ReentrancyGuard {
    bytes32 private constant MANAGER_ROLE = keccak256("REBALANCE_MANAGER");
    bytes32 private constant LAUNCHER_ROLE = keccak256("AUCTION_LAUNCHER");

    struct TokenRule {
        address token;
        uint256 minWeight;
        uint256 maxWeight;
        uint256 maxTradeAmount;
    }

    struct Config {
        address proposer;
        address reviewer;
        address guardian;
        uint256 notice;
        uint256 interval;
        uint256 auctionLength;
        uint256 maxPriceSpreadBps;
        bytes32 methodologyHash;
    }

    // Role ids: 0 proposer, 1 reviewer, 2 guardian. Both OTHER holders must authorize replacement.
    struct RoleChange {
        address replacement;
        address requestedBy;
        uint256 nonce;
        uint256 version;
        uint256 readyAt;
        uint256 expiresAt;
    }

    Folio public immutable index;
    Config public config;
    TokenRule[] public rules;
    bool public activated;
    bytes32 public pending;
    uint256 public readyAt;
    uint256 public expiresAt;
    uint256 public approvedUntil;
    uint256 public nextExecutionAt;
    uint256 public proposalNonce;
    uint256 public activeAuctionPlusOne;
    uint256 public authorityVersion = 1;
    uint256 public roleChangeNonce;
    mapping(uint8 => RoleChange) public roleChanges;

    /// @notice Read by tooling to tell a v3 mandate (fresh prices at approval) from v2, which has no such getter.
    uint256 public constant MANDATE_VERSION = 3;
    /// @notice How far one fresh price may sit from its queued reference: 15%, either way.
    uint256 public constant MAX_REPRICE_BPS = 1500;
    /// @notice How far the fresh prices may move relative to each other since the queue: 5%. This is
    ///         the most a reviewer can shift any pair against the index.
    uint256 public constant MAX_RELATIVE_BPS = 500;
    /// @notice How far past the fresh price an auction may end, per side, at most: 1%, so a pair ends at
    ///         most about 2% past today's prices. Enough for a filler to cover a round trip through thin
    ///         stock pools (measured about 1.1% on a mainnet fork); competing fillers take less. A band
    ///         narrower than three edges gets a third of its width instead.
    uint256 public constant EDGE_BPS = 100;
    /// The proposal the fresh prices were approved for, and the prices, in token order.
    bytes32 public approvedHash;
    IFolio.PriceRange[] private _approvedPrices;

    /**
     * Adding a token to what the index may hold.
     *
     * The universe is not frozen at launch: a creator who cannot add next month's token has an
     * index that ages. It grows only by announcement. A new token, with its limits, is announced
     * and waits at least a week (longer if the index's own notice is longer) before any rebalance
     * can use it, so holders see it coming and can redeem for free first. Any role holder can
     * cancel an announcement. Removing needs no ceremony: a rebalance to weight zero sells a token
     * out, Folio drops it from the basket, and `retireToken` then frees its slot.
     */
    struct PendingToken {
        TokenRule rule;
        uint256 readyAt;
    }

    uint256 public constant MAX_TOKENS = 16;
    uint256 public constant MIN_ADDITION_NOTICE = 7 days;
    PendingToken[] private _pendingTokens;

    error Unauthorized();
    error InvalidPolicy();
    error InvalidProposal();
    error WrongState();
    error TooEarly();
    error ApprovalExpired();

    event ProposalQueued(bytes32 indexed hash, uint256 indexed nonce, uint256 readyAt, uint256 expiresAt,
        IFolio.TokenRebalanceParams[] tokens);
    event ProposalApproved(bytes32 indexed hash, uint256 until);
    event PricesApproved(bytes32 indexed hash, IFolio.PriceRange[] prices);
    event ProposalExecuted(bytes32 indexed hash, uint256 indexed auctionId, uint256 indexed rebalanceNonce);
    event Cancelled(bytes32 indexed pendingHash, uint256 activeAuctionPlusOne);
    event RoleChangeRequested(uint8 indexed role, uint256 indexed nonce, address indexed replacement,
        address requestedBy, uint256 authorityVersion, uint256 expiresAt);
    event RoleChangeConfirmed(uint8 indexed role, uint256 indexed nonce, uint256 readyAt, uint256 expiresAt);
    event RoleChangeCancelled(uint8 indexed role, uint256 indexed nonce);
    event RoleChanged(uint8 indexed role, uint256 indexed nonce, address indexed replacement,
        address previous, uint256 authorityVersion);
    event TokenAnnounced(address indexed token, uint256 readyAt, uint256 maxWeight, uint256 maxTradeAmount);
    event TokenAnnouncementCancelled(address indexed token);
    event TokenAdded(address indexed token);
    event TokenRetired(address indexed token);

    constructor(Folio index_, Config memory cfg, TokenRule[] memory tokenRules) {
        /*
         * One wallet may hold every role: a creator can run an index alone. What an independent
         * reviewer would have added is a second pair of eyes on prices; without one, holders get
         * time instead. A self-reviewed rebalance must be announced a full day ahead, and
         * redemption is always free, so anyone who dislikes it can leave before it executes.
         */
        if (address(index_).code.length == 0 || cfg.proposer == address(0) || cfg.reviewer == address(0)
            || cfg.guardian == address(0) || cfg.notice < 1 hours
            || (cfg.reviewer == cfg.proposer && cfg.notice < SELF_REVIEW_NOTICE)
            || cfg.interval < 28 days || cfg.auctionLength < 120 || cfg.auctionLength > 1 hours
            || cfg.maxPriceSpreadBps == 0 || cfg.maxPriceSpreadBps > 500
            || cfg.methodologyHash == bytes32(0) || tokenRules.length < 2 || tokenRules.length > 16) revert InvalidPolicy();
        index = index_;
        config = cfg;
        for (uint256 i; i < tokenRules.length; ++i) {
            TokenRule memory r = tokenRules[i];
            if (r.token.code.length == 0 || r.token == address(index_) || r.maxWeight == 0
                || r.minWeight > r.maxWeight || r.maxWeight > 1e54 || r.maxTradeAmount == 0) revert InvalidPolicy();
            for (uint256 j; j < i; ++j) if (tokenRules[j].token == r.token) revert InvalidPolicy();
            rules.push(r);
        }
    }

    /// @dev Called after atomic role handoff. Verifies there is no bypass role left on the engine.
    function activate() external {
        if (activated) revert WrongState();
        _checkRoles();
        (bool weightControl, IFolio.PriceControl priceControl) = index.rebalanceControl();
        if (weightControl || priceControl != IFolio.PriceControl.NONE || index.trustedFillerEnabled()
            || !index.bidsEnabled() || index.maxAuctionLength() != config.auctionLength) revert InvalidPolicy();
        (address[] memory assets,) = index.totalAssets();
        if (assets.length != rules.length) revert InvalidPolicy();
        for (uint256 i; i < assets.length; ++i) if (assets[i] != rules[i].token) revert InvalidPolicy();
        activated = true;
    }

    /// @notice The shortest notice allowed when the proposer also approves prices.
    uint256 public constant SELF_REVIEW_NOTICE = 24 hours;

    function _checkRoles() private view {
        if (index.getRoleMemberCount(bytes32(0)) != 1 || !index.hasRole(bytes32(0), address(this))
            || index.getRoleMemberCount(MANAGER_ROLE) != 1 || !index.hasRole(MANAGER_ROLE, address(this))
            || index.getRoleMemberCount(LAUNCHER_ROLE) != 1 || !index.hasRole(LAUNCHER_ROLE, address(this))) revert InvalidPolicy();
    }

    function ruleCount() external view returns (uint256) { return rules.length; }

    function roleChangeDelay() public view returns (uint256) {
        return config.notice > 7 days ? config.notice : 7 days;
    }

    function _holder(uint8 role) private view returns (address) {
        if (role == 0) return config.proposer;
        if (role == 1) return config.reviewer;
        if (role == 2) return config.guardian;
        revert InvalidPolicy();
    }

    function _checkRecoveryAuthority(uint8 role) private view {
        if (msg.sender == _holder(role) || (msg.sender != config.proposer
            && msg.sender != config.reviewer && msg.sender != config.guardian)) revert Unauthorized();
    }

    /// @notice One surviving holder requests; the other confirms. Replacing a request resets all approvals.
    function requestRoleChange(uint8 role, address replacement) external {
        _checkRecoveryAuthority(role);
        if (!activated || replacement == address(0) || replacement == config.proposer
            || replacement == config.reviewer || replacement == config.guardian
            || replacement == address(this) || replacement == address(index)) revert InvalidPolicy();
        uint256 nonce = ++roleChangeNonce;
        roleChanges[role] = RoleChange(replacement, msg.sender, nonce, authorityVersion, 0, block.timestamp + 7 days);
        emit RoleChangeRequested(role, nonce, replacement, msg.sender, authorityVersion, block.timestamp + 7 days);
    }

    function _currentChange(uint8 role, uint256 nonce) private view returns (RoleChange storage change) {
        change = roleChanges[role];
        if (change.replacement == address(0) || change.nonce != nonce || change.version != authorityVersion
            || block.timestamp > change.expiresAt) revert WrongState();
    }

    /// @notice Investor notice starts only after both surviving holders agree to this exact request.
    function confirmRoleChange(uint8 role, uint256 nonce) external {
        _checkRecoveryAuthority(role);
        RoleChange storage change = _currentChange(role, nonce);
        if (msg.sender == change.requestedBy) revert Unauthorized();
        if (change.readyAt != 0) revert WrongState();
        change.readyAt = block.timestamp + roleChangeDelay();
        change.expiresAt = change.readyAt + 7 days;
        emit RoleChangeConfirmed(role, nonce, change.readyAt, change.expiresAt);
    }

    /// @notice Either authorizing holder can withdraw consent; the holder being replaced cannot veto recovery.
    function cancelRoleChange(uint8 role, uint256 nonce) external {
        _checkRecoveryAuthority(role);
        _currentChange(role, nonce);
        delete roleChanges[role];
        emit RoleChangeCancelled(role, nonce);
    }

    /// @notice The replacement wallet accepts after notice. All other requests and old proposals become invalid.
    function acceptRoleChange(uint8 role, uint256 nonce) external nonReentrant {
        RoleChange memory change = _currentChange(role, nonce);
        if (msg.sender != change.replacement) revert Unauthorized();
        if (change.readyAt == 0 || block.timestamp < change.readyAt) revert TooEarly();
        _checkRoles();
        address previous = _holder(role);
        _cancelExecution();
        if (role == 0) config.proposer = change.replacement;
        else if (role == 1) config.reviewer = change.replacement;
        else config.guardian = change.replacement;
        ++authorityVersion;
        delete roleChanges[role];
        emit RoleChanged(role, nonce, change.replacement, previous, authorityVersion);
    }

    function proposalHash(IFolio.TokenRebalanceParams[] calldata tokens, uint256 nonce, uint256 expiry)
        public view returns (bytes32)
    {
        return keccak256(abi.encode(block.chainid, address(this), address(index), config.methodologyHash,
            authorityVersion, nonce, expiry, tokens));
    }

    function queue(IFolio.TokenRebalanceParams[] calldata tokens, uint256 expiry) external {
        if (msg.sender != config.proposer) revert Unauthorized();
        if (!activated || pending != bytes32(0)) revert WrongState();
        if (expiry < block.timestamp + config.notice + 60 || expiry > block.timestamp + config.notice + 7 days) {
            revert InvalidProposal();
        }
        _validate(tokens);
        pending = proposalHash(tokens, ++proposalNonce, expiry);
        readyAt = block.timestamp + config.notice;
        expiresAt = expiry;
        _clearApproval();
        emit ProposalQueued(pending, proposalNonce, readyAt, expiry, tokens);
    }

    /// @notice Reviewer approves the queued proposal with fresh prices, shortly before execution.
    /// @param tokens The proposal exactly as queued: it is checked against the commitment.
    /// @param prices One fresh price per token, D27 USD per raw unit as Folio prices, in the proposal's
    ///        order. The auction's bands are built from these here, not supplied.
    /// @dev   Calling again before execution replaces both the prices and the window.
    function approve(IFolio.TokenRebalanceParams[] calldata tokens, uint256[] calldata prices, uint256 until) external {
        if (msg.sender != config.reviewer) revert Unauthorized();
        bytes32 hash = pending;
        if (hash == bytes32(0) || proposalHash(tokens, proposalNonce, expiresAt) != hash || block.timestamp < readyAt) {
            revert WrongState();
        }
        if (until <= block.timestamp || until > block.timestamp + 5 minutes || until > expiresAt) revert InvalidProposal();
        if (prices.length != tokens.length) revert InvalidProposal();
        _checkRelative(tokens, prices);
        (address[] memory held, uint256[] memory perShare) = index.toAssets(1e18, Math.Rounding.Floor);
        delete _approvedPrices;
        for (uint256 i; i < prices.length; ++i) {
            uint256 current;
            for (uint256 j; j < held.length; ++j) if (held[j] == tokens[i].token) current = perShare[j] * 1e9;
            _approvedPrices.push(_band(prices[i], tokens[i].weight.spot, current));
        }
        approvedHash = hash;
        approvedUntil = until;
        emit ProposalApproved(hash, until);
        emit PricesApproved(hash, _approvedPrices);
    }

    /// Each fresh price within `MAX_REPRICE_BPS` of its reference, and all of them within
    /// `MAX_RELATIVE_BPS` of each other, measured as moves from their references.
    function _checkRelative(IFolio.TokenRebalanceParams[] calldata tokens, uint256[] calldata prices) private pure {
        uint256 lo = type(uint256).max;
        uint256 hi;
        for (uint256 i; i < prices.length; ++i) {
            uint256 ref = tokens[i].price.low;
            uint256 p = prices[i];
            if (p == 0 || p > 1e45 || p * 10_000 < ref * (10_000 - MAX_REPRICE_BPS)
                || p * 10_000 > ref * (10_000 + MAX_REPRICE_BPS)) revert InvalidProposal();
            uint256 move = p * 1e18 / ref;
            if (move < lo) lo = move;
            if (move > hi) hi = move;
        }
        if (hi * 10_000 > lo * (10_000 + MAX_RELATIVE_BPS)) revert InvalidProposal();
    }

    /// The auction band for one token: the index sells it if its target is below what a share holds
    /// now, buys it if above. Folio runs a pair from sell-high over buy-low down to sell-low over
    /// buy-high, so this shape starts every pair in the index's favour and ends it just past `p`.
    function _band(uint256 p, uint256 target, uint256 current) private view returns (IFolio.PriceRange memory r) {
        uint256 w = config.maxPriceSpreadBps;
        uint256 edge = w / 3 < EDGE_BPS ? w / 3 : EDGE_BPS;
        if (target < current) {
            r.low = p * (10_000 - edge) / 10_000;
            r.high = r.low + r.low * w / 10_000;
        } else if (target > current) {
            r.high = p * (10_000 + edge) / 10_000;
            r.low = Math.mulDiv(r.high, 10_000, 10_000 + w, Math.Rounding.Ceil);
        } else {
            r.low = p * (20_000 - w) / 20_000;
            r.high = r.low + r.low * w / 10_000;
        }
        if (r.low == 0 || r.high <= r.low || r.high > 1e45) revert InvalidProposal();
    }

    /// @notice The fresh bands the current approval will open the auction with; empty when none.
    function approvedPrices() external view returns (IFolio.PriceRange[] memory) {
        return _approvedPrices;
    }

    function execute(IFolio.TokenRebalanceParams[] calldata tokens) external nonReentrant returns (uint256 auctionId) {
        if (!activated || pending == bytes32(0) || proposalHash(tokens, proposalNonce, expiresAt) != pending) revert WrongState();
        if (block.timestamp < readyAt || block.timestamp < nextExecutionAt) revert TooEarly();
        if (block.timestamp > expiresAt || approvedUntil == 0 || block.timestamp > approvedUntil) revert ApprovalExpired();
        bytes32 hash = pending;
        // Belt and braces: every path that changes `pending` also clears the approval, so this cannot
        // fire today. It keeps an approval bound to its proposal if a later change forgets to.
        if (approvedHash != hash || _approvedPrices.length != tokens.length) revert ApprovalExpired();
        _checkRoles();
        _validate(tokens);
        // The auction runs on the fresh bands approved minutes ago, never on the queued reference.
        IFolio.TokenRebalanceParams[] memory fresh = tokens;
        address[] memory assets = new address[](tokens.length);
        IFolio.WeightRange[] memory weights = new IFolio.WeightRange[](tokens.length);
        IFolio.PriceRange[] memory prices = new IFolio.PriceRange[](tokens.length);
        for (uint256 i; i < tokens.length; ++i) {
            fresh[i].price = _approvedPrices[i];
            assets[i] = tokens[i].token;
            weights[i] = tokens[i].weight;
            prices[i] = _approvedPrices[i];
        }
        _clearApproval();
        pending = bytes32(0);
        nextExecutionAt = block.timestamp + config.interval;
        uint256 nonce = index.getRebalanceNonce() + 1;
        IFolio.RebalanceLimits memory limits = IFolio.RebalanceLimits(1e18, 1e18, 1e18);
        uint256 ttl = config.auctionLength + 31;
        index.startRebalance(nonce, fresh, limits, ttl, ttl, block.timestamp);
        auctionId = index.openAuction(nonce, assets, weights, prices, limits, config.auctionLength);
        // Ending a rebalance blocks further auctions but leaves this auction open until its deadline.
        // Thus Folio's per-auction volume cap cannot be multiplied by opening another auction.
        index.endRebalance(nonce);
        activeAuctionPlusOne = auctionId + 1;
        emit ProposalExecuted(hash, auctionId, nonce);
    }

    function _validate(IFolio.TokenRebalanceParams[] calldata tokens) private view {
        if (tokens.length != rules.length) revert InvalidProposal();
        for (uint256 i; i < tokens.length; ++i) {
            IFolio.TokenRebalanceParams calldata t = tokens[i];
            TokenRule storage r = rules[i];
            if (t.token != r.token || !t.inRebalance || t.weight.low != t.weight.spot
                || t.weight.spot != t.weight.high || t.weight.low < r.minWeight || t.weight.high > r.maxWeight
                || t.maxAuctionSize == 0 || t.maxAuctionSize > r.maxTradeAmount
                || t.price.low == 0 || t.price.high <= t.price.low || t.price.high > 1e45
                || t.price.high - t.price.low > t.price.low * config.maxPriceSpreadBps / 10_000) revert InvalidProposal();
        }
    }

    /// @notice Cancellation never refunds the consumed monthly execution budget.
    function cancel() external nonReentrant {
        if (msg.sender != config.guardian && msg.sender != config.reviewer) revert Unauthorized();
        _cancelExecution();
    }

    function _cancelExecution() private {
        emit Cancelled(pending, activeAuctionPlusOne);
        pending = bytes32(0);
        _clearApproval();
        readyAt = 0;
        expiresAt = 0;
        if (activeAuctionPlusOne != 0) {
            index.closeAuction(activeAuctionPlusOne - 1);
            activeAuctionPlusOne = 0;
        }
    }

    /* -------------------------------------------------------------- the token universe */

    function additionDelay() public view returns (uint256) {
        return config.notice > MIN_ADDITION_NOTICE ? config.notice : MIN_ADDITION_NOTICE;
    }

    function pendingTokens() external view returns (PendingToken[] memory) {
        return _pendingTokens;
    }

    /// @notice Announce a token the index may hold from `additionDelay()` from now. Proposer only.
    /// @dev    A new token starts with no floor (`minWeight` 0): adding it never forces a purchase.
    function announceToken(TokenRule calldata r) external {
        if (msg.sender != config.proposer) revert Unauthorized();
        if (!activated) revert WrongState();
        if (rules.length + _pendingTokens.length >= MAX_TOKENS || r.token.code.length == 0
            || r.token == address(index) || r.token == address(this) || r.minWeight != 0 || r.maxWeight == 0
            || r.maxWeight > 1e54 || r.maxTradeAmount == 0 || _ruleIndex(r.token) != type(uint256).max
            || _pendingIndex(r.token) != type(uint256).max) revert InvalidPolicy();
        uint256 ready = block.timestamp + additionDelay();
        _pendingTokens.push(PendingToken(r, ready));
        emit TokenAnnounced(r.token, ready, r.maxWeight, r.maxTradeAmount);
    }

    /// @notice Withdraw an announcement before it is added. Any role holder.
    function cancelToken(address token) external {
        if (msg.sender != config.proposer && msg.sender != config.reviewer && msg.sender != config.guardian) revert Unauthorized();
        uint256 i = _pendingIndex(token);
        if (i == type(uint256).max) revert WrongState();
        _removePending(i);
        emit TokenAnnouncementCancelled(token);
    }

    /// @notice Make an announced token part of the universe once its wait is over. Proposer only.
    /// @dev    Only between rebalances: a proposal commits to the exact token list it was queued with.
    function addToken(address token) external {
        if (msg.sender != config.proposer) revert Unauthorized();
        _checkQuiet();
        uint256 i = _pendingIndex(token);
        if (i == type(uint256).max) revert WrongState();
        if (block.timestamp < _pendingTokens[i].readyAt) revert TooEarly();
        rules.push(_pendingTokens[i].rule);
        _removePending(i);
        emit TokenAdded(token);
    }

    /// @notice Drop a token the index no longer holds from its universe, freeing a slot. Proposer only.
    /// @dev    Only once Folio has removed it from the basket, which happens when a rebalance sells it
    ///         out. The universe never falls below two tokens.
    function retireToken(address token) external {
        if (msg.sender != config.proposer) revert Unauthorized();
        _checkQuiet();
        uint256 i = _ruleIndex(token);
        if (i == type(uint256).max || rules.length <= 2) revert InvalidPolicy();
        (address[] memory held,) = index.totalAssets();
        for (uint256 j; j < held.length; ++j) if (held[j] == token) revert WrongState();
        rules[i] = rules[rules.length - 1];
        rules.pop();
        emit TokenRetired(token);
    }

    function _checkQuiet() private view {
        if (!activated || pending != bytes32(0)) revert WrongState();
        if (activeAuctionPlusOne != 0) {
            (,, uint256 endTime) = index.auctions(activeAuctionPlusOne - 1);
            if (block.timestamp <= endTime) revert WrongState();
        }
    }

    function _ruleIndex(address token) private view returns (uint256) {
        for (uint256 i; i < rules.length; ++i) if (rules[i].token == token) return i;
        return type(uint256).max;
    }

    function _pendingIndex(address token) private view returns (uint256) {
        for (uint256 i; i < _pendingTokens.length; ++i) if (_pendingTokens[i].rule.token == token) return i;
        return type(uint256).max;
    }

    function _removePending(uint256 i) private {
        _pendingTokens[i] = _pendingTokens[_pendingTokens.length - 1];
        _pendingTokens.pop();
    }

    function clearExpired() external {
        if (pending == bytes32(0) || block.timestamp <= expiresAt) revert WrongState();
        emit Cancelled(pending, 0);
        pending = bytes32(0);
        _clearApproval();
    }

    function _clearApproval() private {
        approvedUntil = 0;
        approvedHash = bytes32(0);
        delete _approvedPrices;
    }
}

src/MandateDeployer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Folio} from "folio/Folio.sol";
import {MonthlyMandate} from "./MonthlyMandate.sol";

/**
 * Holds `MonthlyMandate`'s creation code so the factory does not have to.
 *
 * A contract that deploys another carries the other's whole creation code in its own runtime, and
 * the mandate is large enough to push `IndexFactory` past the 24,576-byte limit. The factory creates
 * one of these in its constructor and asks it for each mandate instead.
 *
 * Stateless and permissionless on purpose. Anyone may deploy a mandate through it, which gives them
 * nothing: a mandate has no power over an index until that index grants it roles, and only the
 * factory's launch path does that.
 */
contract MandateDeployer {
    function deploy(Folio index, MonthlyMandate.Config calldata cfg, MonthlyMandate.TokenRule[] calldata rules)
        external returns (MonthlyMandate)
    {
        return new MonthlyMandate(index, cfg, rules);
    }
}

src/ShareMarketRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IPoolManager} from "v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {PoolKey} from "v4-core/src/types/PoolKey.sol";
import {PoolId} from "v4-core/src/types/PoolId.sol";
import {Currency} from "v4-core/src/types/Currency.sol";
import {BalanceDelta} from "v4-core/src/types/BalanceDelta.sol";
import {SwapParams, ModifyLiquidityParams} from "v4-core/src/types/PoolOperation.sol";
import {StateLibrary} from "v4-core/src/libraries/StateLibrary.sol";

/// @notice ERC20-only router for ordinary v4 share markets, hookless or carrying the one known fee hook.
/// @dev No approvals to PoolManager, persistent custody, NAV dependency or constituent execution.
/// LP positions belong to msg.sender through a namespaced salt. Not independently audited.
contract ShareMarketRouter is IUnlockCallback, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using StateLibrary for IPoolManager;

    IPoolManager public immutable manager;
    bool private unlocking;

    error InvalidMarket();
    error Expired();
    error InvalidAmount();
    error Slippage();
    error UnauthorizedCallback();
    error QuoteResult(int256 delta);
    error UnexpectedQuoteResult();

    /// Net deltas are from the owner's perspective: negative pays in, positive receives.
    /// Settled fees are included in netDelta, never additional proceeds.
    event LiquidityChanged(address indexed owner, bytes32 indexed poolId, bytes32 indexed position,
        address currency0, address currency1, int24 lower, int24 upper, int256 liquidityDelta,
        int256 netDelta, int256 feeDelta);

    struct Request {
        address payer;
        address owner;
        PoolKey key;
        bool swap;
        bool quote;
        bool zeroForOne;
        uint256 amount;
        uint160 priceLimit;
        ModifyLiquidityParams position;
        uint256 limit0;
        uint256 limit1;
    }

    /// @notice The one hook this router will trade through, besides no hook at all.
    /// @dev    Immutable and singular on purpose. The original rule here was "no hooks", which
    ///         was the right guarantee and the wrong shape: the fee has to come from somewhere
    ///         and `ShareFeeHook` is where it comes from. Allowing exactly one known address
    ///         keeps what the rule was protecting, which is that this router never hands a swap
    ///         to code nobody chose. Set it to the zero address for a hookless-only deployment.
    address public immutable feeHook;

    /// @notice The one contract allowed to open a position on somebody else's behalf.
    /// @dev    The factory, so a launch can seed the market in the same transaction that creates
    ///         the index. It can only ever ADD liquidity and only ever to the owner it names;
    ///         removal still derives its salt from `msg.sender`, so nobody can be relieved of a
    ///         position they hold. Zero disables the path entirely.
    address public immutable launcher;

    constructor(IPoolManager manager_, address feeHook_, address launcher_) {
        if (address(manager_).code.length == 0) revert InvalidMarket();
        manager = manager_;
        feeHook = feeHook_;
        launcher = launcher_;
    }

    function positionSalt(address owner, bytes32 userSalt) public pure returns (bytes32) {
        return keccak256(abi.encode(owner, userSalt));
    }

    /// @notice Simulates native pricing without approvals or funds. Inner pool changes are reverted.
    function quoteExactInput(PoolKey calldata key, bool zeroForOne, uint256 amountIn, uint160 priceLimit)
        external nonReentrant returns (BalanceDelta delta)
    {
        _validate(key, type(uint256).max);
        if (amountIn == 0 || amountIn > uint256(uint128(type(int128).max))) revert InvalidAmount();
        Request memory r;
        r.key = key;
        r.swap = true;
        r.quote = true;
        r.zeroForOne = zeroForOne;
        r.amount = amountIn;
        r.priceLimit = priceLimit;
        unlocking = true;
        try manager.unlock(abi.encode(r)) returns (bytes memory) {
            revert UnexpectedQuoteResult();
        } catch (bytes memory reason) {
            unlocking = false;
            if (reason.length != 36 || bytes4(reason) != QuoteResult.selector) {
                assembly ("memory-safe") { revert(add(reason, 32), mload(reason)) }
            }
            int256 packed;
            assembly ("memory-safe") { packed := mload(add(reason, 36)) }
            return BalanceDelta.wrap(packed);
        }
    }

    function marketState(PoolKey calldata key) external view
        returns (uint160 sqrtPriceX96, int24 tick, uint24 protocolFee, uint24 lpFee, uint128 liquidity)
    {
        (sqrtPriceX96, tick, protocolFee, lpFee) = manager.getSlot0(key.toId());
        liquidity = manager.getLiquidity(key.toId());
    }

    function positionLiquidity(PoolKey calldata key, address owner, int24 lower, int24 upper, bytes32 userSalt)
        external view returns (uint128 liquidity)
    {
        (liquidity,,) = manager.getPositionInfo(key.toId(), address(this), lower, upper, positionSalt(owner, userSalt));
    }

    function swapExactInput(
        PoolKey calldata key,
        bool zeroForOne,
        uint256 amountIn,
        uint256 minOut,
        uint160 priceLimit,
        uint256 deadline
    ) external nonReentrant returns (BalanceDelta delta) {
        _validate(key, deadline);
        if (amountIn == 0 || amountIn > uint256(uint128(type(int128).max))) revert InvalidAmount();
        Request memory r;
        r.payer = msg.sender;
        r.key = key;
        r.swap = true;
        r.zeroForOne = zeroForOne;
        r.amount = amountIn;
        r.priceLimit = priceLimit;
        r.limit0 = minOut;
        return _unlock(r);
    }

    /// @param limit0 Maximum token0 payment on add; minimum token0 receipt on remove/collect.
    /// @param limit1 Maximum token1 payment on add; minimum token1 receipt on remove/collect.
    function modifyLiquidity(
        PoolKey calldata key,
        ModifyLiquidityParams calldata params,
        uint256 limit0,
        uint256 limit1,
        uint256 deadline
    ) external nonReentrant returns (BalanceDelta delta) {
        _validate(key, deadline);
        Request memory r;
        r.payer = msg.sender;
        r.key = key;
        r.position = params;
        r.position.salt = positionSalt(msg.sender, params.salt);
        r.owner = msg.sender;
        r.limit0 = limit0;
        r.limit1 = limit1;
        return _unlock(r);
    }

    /**
     * @notice Open a position owned by `owner`, paid for by the caller. Launcher only.
     *
     * @dev    Exists so an index is tradeable in the same transaction it is created. Without it
     *         a launch produces a share with no market, which is the cold-start problem this
     *         design has and the retired dealer design did not.
     *
     *         Three bounds, and they are what make lending the salt safe:
     *
     *         1. **Only the launcher may call it.** One immutable address, set at construction.
     *         2. **It may only add.** A negative delta is refused, so this can never be used to
     *            take a position away from the person who holds it.
     *         3. **Removal is unchanged.** Withdrawal still derives its salt from `msg.sender`,
     *            so the owner named here, and nobody else, can ever get these funds out.
     */
    function modifyLiquidityFor(
        address owner,
        PoolKey calldata key,
        ModifyLiquidityParams calldata params,
        uint256 limit0,
        uint256 limit1,
        uint256 deadline
    ) external nonReentrant returns (BalanceDelta delta) {
        if (msg.sender != launcher || launcher == address(0)) revert InvalidMarket();
        if (params.liquidityDelta <= 0) revert InvalidAmount();
        _validate(key, deadline);
        Request memory r;
        r.key = key;
        r.position = params;
        r.position.salt = positionSalt(owner, params.salt);
        r.payer = msg.sender;
        // The factory pays for a launch seed, but the position is the creator's, and the event
        // is what the indexer attributes it by.
        r.owner = owner;
        r.limit0 = limit0;
        r.limit1 = limit1;
        return _unlock(r);
    }

    function _validate(PoolKey calldata key, uint256 deadline) private view {
        if (block.timestamp > deadline) revert Expired();
        /*
         * No hook, or the one hook this router was deployed to know.
         *
         * A user is still protected by `minOut` rather than by the absence of a hook: the fee is
         * taken from the output and the swap reverts if what arrives is short. That is the same
         * bound that protects them from price impact, and it does not care why the output was
         * smaller than they hoped.
         */
        address hooks = address(key.hooks);
        if ((hooks != address(0) && hooks != feeHook) || Currency.unwrap(key.currency0) == address(0)
            || Currency.unwrap(key.currency0) >= Currency.unwrap(key.currency1)) revert InvalidMarket();
    }

    function _unlock(Request memory r) private returns (BalanceDelta) {
        unlocking = true;
        bytes memory result = manager.unlock(abi.encode(r));
        unlocking = false;
        return abi.decode(result, (BalanceDelta));
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(manager) || !unlocking) revert UnauthorizedCallback();
        Request memory r = abi.decode(data, (Request));
        BalanceDelta delta;
        BalanceDelta fees;
        if (r.swap) {
            delta = manager.swap(r.key, SwapParams(r.zeroForOne, -int256(r.amount), r.priceLimit), "");
            if (r.quote) revert QuoteResult(BalanceDelta.unwrap(delta));
            int128 input = r.zeroForOne ? delta.amount0() : delta.amount1();
            int128 output = r.zeroForOne ? delta.amount1() : delta.amount0();
            if (input >= 0 || output <= 0 || uint256(-int256(input)) > r.amount
                || uint256(int256(output)) < r.limit0) revert Slippage();
        } else {
            (delta,fees) = manager.modifyLiquidity(r.key, r.position, "");
            if (r.position.liquidityDelta > 0) {
                if (_owed(delta.amount0()) > r.limit0 || _owed(delta.amount1()) > r.limit1) revert Slippage();
            } else if (delta.amount0() < 0 || delta.amount1() < 0
                || uint256(int256(delta.amount0())) < r.limit0
                || uint256(int256(delta.amount1())) < r.limit1) revert Slippage();
        }
        _settle(r.key.currency0, r.payer, delta.amount0());
        _settle(r.key.currency1, r.payer, delta.amount1());
        if (!r.swap) emit LiquidityChanged(r.owner, PoolId.unwrap(r.key.toId()), r.position.salt,
            Currency.unwrap(r.key.currency0), Currency.unwrap(r.key.currency1), r.position.tickLower,
            r.position.tickUpper, r.position.liquidityDelta, BalanceDelta.unwrap(delta), BalanceDelta.unwrap(fees));
        return abi.encode(delta);
    }

    function _owed(int128 amount) private pure returns (uint256) {
        return amount < 0 ? uint256(-int256(amount)) : 0;
    }

    function _settle(Currency currency, address payer, int128 amount) private {
        if (amount < 0) {
            manager.sync(currency);
            IERC20(Currency.unwrap(currency)).safeTransferFrom(payer, address(manager), _owed(amount));
            manager.settle();
        } else if (amount > 0) {
            manager.take(currency, payer, uint256(int256(amount)));
        }
    }
}

